### 8. Webhook signature verifier with timestamp tolerance and constant-time compare

```ts
import { createHmac, timingSafeEqual } from 'node:crypto';

export interface VerifyOptions {
  rawBody: Buffer;              // the EXACT bytes received, before any JSON parsing
  header: string | undefined;   // e.g. "t=1714560000,v1=6f8a...,v1=9c2b..."  (one per active secret)
  secret: string;               // or string[] during rotation
  toleranceSeconds?: number;
  now?: number;
}
export type VerifyResult =
  | { ok: true; timestamp: number }
  | { ok: false; reason: 'missing' | 'malformed' | 'stale' | 'no-matching-secret' | 'bad-signature' };

export function verifyWebhook(o: VerifyOptions): VerifyResult {
  const tolerance = o.toleranceSeconds ?? 300;                    // 5 minutes
  if (!o.header) return { ok: false, reason: 'missing' };
  if (o.rawBody.length === 0) return { ok: false, reason: 'malformed' };
  if (o.rawBody.length > 5 * 1024 * 1024) return { ok: false, reason: 'malformed' };

  // 1. Parse the header into timestamp + the list of candidate signatures.
  const ts: number[] = [], sigs: string[] = [];
  for (const part of o.header.split(',')) {
    const idx = part.indexOf('=');
    if (idx < 0) continue;
    const k = part.slice(0, idx).trim(), v = part.slice(idx + 1).trim();
    if (k === 't') ts.push(Number(v));
    if (k === 'v1' && /^[0-9a-f]{64}$/i.test(v)) sigs.push(v.toLowerCase());   // hex HMAC only
  }
  const timestamp = ts[0];
  if (!Number.isFinite(timestamp) || sigs.length === 0) return { ok: false, reason: 'malformed' };

  // 2. Replay window. Compare absolute skew so a future-dated timestamp is rejected too.
  const skew = Math.abs((o.now ?? Date.now()) / 1000 - timestamp);
  if (skew > tolerance) return { ok: false, reason: 'stale' };

  // 3. Sign timestamp + "." + raw body. The timestamp inside the signed material is what
  //    stops a captured (body, signature) pair from being replayed with a fresh t=.
  const secrets = Array.isArray(o.secret) ? o.secret : [o.secret];
  let matched = false;
  for (const secret of secrets) {
    const expected = createHmac('sha256', secret).update(`${timestamp}.`).update(o.rawBody).digest();
    for (const sig of sigs) {
      const given = Buffer.from(sig, 'hex');
      // length check first: timingSafeEqual throws on a length mismatch.
      if (given.length === expected.length && timingSafeEqual(given, expected)) { matched = true; break; }
    }
    if (matched) break;
  }
  return matched ? { ok: true, timestamp } : { ok: false, reason: 'bad-signature' };
}

// Raw-body capture you need for the verifier to work at all:
app.post('/webhooks/stripe',
  express.raw({ type: 'application/json' }),                 // Buffer, not an object
  (req, res) => {
    const verdict = verifyWebhook({ rawBody: req.body, header: req.header('stripe-signature'),
                                    secret: process.env.STRIPE_SECRET! });
    if (!verdict.ok) return res.status(400).type('application/problem+json')
      .json({ type: 'bad-signature', title: 'Bad request', status: 400, code: 'INVALID_SIGNATURE' });
    const event = JSON.parse(req.body.toString());
    // Atomic dedupe: the insert's conflict result IS the idempotency check.
    void enqueue(event).catch((err) => res.status(500).end());
    res.status(200).end();                                     // fast 2xx, process async
  });
```
*Edge cases:* **verifying after re-serializing the parsed body** (the signature will not match â€” this is the classic bug); signing the body without the timestamp (replayable forever); naive `===` (byte-by-byte timing leak); `timingSafeEqual` throwing on a length mismatch; **secret rotation** (emit one `v1=` per active secret and accept any â€” hence `string[]`); a header with several `v1=` values for the same secret; a non-hex or wrong-length signature; a timestamp in seconds vs milliseconds; a clock skew that rejects valid deliveries (the tolerance, and the receiver's NTP requirement); a signature replayed within the tolerance window (the tolerance is the mitigation â€” hence also dedupe on `id`); multiple headers with the same name; `t=` present but no `v1=`; and a very large body (cap it before hashing, or a single request can make you hash 100 MB).

---

### 9. GraphQL query depth and complexity validator

```ts
type FieldInfo = { name: string; type: TypeInfo; args: Record<string, unknown> };
type TypeInfo = { kind: 'scalar' | 'object' | 'union' | 'interface' | 'enum'; name: string; ofType?: TypeInfo };
interface TypeMap { [name: string]: { fields: Record<string, FieldInfo>; listSizeHint?: number } }

export interface Limits { maxDepth: number; maxCost: number; maxAliases: number; maxRootFields: number }
export type Verdict = { ok: true; cost: number; depth: number } | { ok: false; code: string; message: string; cost?: number };

export function validateQuery(schema: TypeMap, rootType: string, doc: any, limits: Limits): Verdict {
  let cost = 0, depth = 0, aliases = 0, rootFields = 0;
  const fragments = new Map<string, any>(
    (doc.definitions ?? []).filter((d: any) => d.kind === 'FragmentDefinition').map((d: any) => [d.name.value, d]),
  );

  // 1. Depth + cost in one pass. Fragment spreads are expanded with cycle detection.
  const walk = (selections: any[], parentType: string, level: number, visiting: Set<string>): void => {
    if (level > limits.maxDepth) {
      throw Object.assign(new Error('depth limit exceeded'), { code: 'DEPTH_LIMIT' });
    }
    for (const sel of selections ?? []) {
      if (sel.kind === 'Field') {
        aliases += 1;
        const name = sel.name.value;
        const typeInfo = schema[parentType]?.fields?.[name]?.type;
        if (!typeInfo) continue;
        // List fields multiply the cost of everything beneath them. The multiplier is
        // the *effective* page size: the client's `first`, capped by the schema hint.
        const requested = Number((sel.arguments ?? []).find((a: any) => a.name.value === 'first')?.value?.value ?? 0);
        const listSize = typeInfo.kind === 'object' && isList(typeInfo)
          ? Math.min(requested || schema[unwrapped(typeInfo)]?.listSizeHint ?? 10, 200)
          : 1;
        const fieldCost = 1 * listSize;
        cost += fieldCost;
        if (typeInfo.kind === 'object') {
          walk(sel.selectionSet?.selections ?? [], unwrapped(typeInfo).name, level + 1, visiting);
        } else if (typeInfo.kind === 'union' || typeInfo.kind === 'interface') {
          // Only inline fragments can select further fields; charge the widest branch.
          const branches = (sel.selectionSet?.selections ?? []).filter((s: any) => s.kind === 'InlineFragment');
          for (const b of branches) walk(b.selectionSet?.selections ?? [], b.typeCondition?.name?.value ?? parentType, level + 1, visiting);
        }
      } else if (sel.kind === 'InlineFragment') {
        walk(sel.selectionSet?.selections ?? [], sel.typeCondition?.name?.value ?? parentType, level, visiting);
      } else if (sel.kind === 'FragmentSpread') {
        const name = sel.name.value;
        if (visiting.has(name)) {
          throw Object.assign(new Error('fragment cycle'), { code: 'FRAGMENT_CYCLE' });
        }
        const frag = fragments.get(name);
        if (!frag) throw Object.assign(new Error('unknown fragment'), { code: 'UNKNOWN_FRAGMENT' });
        visiting.add(name);
        walk(frag.selectionSet?.selections, frag.typeCondition?.name?.value ?? parentType, level, visiting);
        visiting.delete(name);
      }
    }
  };

  try {
    for (const def of doc.definitions ?? []) {
      if (def.kind !== 'OperationDefinition') continue;
      rootFields += def.selectionSet?.selections?.length ?? 0;
      walk(def.selectionSet?.selections, rootType, 1, new Set());
    }
  } catch (err: any) {
    return { ok: false, code: err.code ?? 'VALIDATION_FAILED', message: err.message };
  }

  if (aliases > limits.maxAliases)     return { ok: false, code: 'ALIAS_LIMIT',   message: `max ${limits.maxAliases} fields per query` };
  if (rootFields > limits.maxRootFields) return { ok: false, code: 'ROOT_LIMIT',  message: `max ${limits.maxRootFields} root fields` };
  if (cost > limits.maxCost)           return { ok: false, code: 'COMPLEXITY_LIMIT', message: `estimated cost ${cost} > ${limits.maxCost}`, cost };
  return { ok: true, cost, depth };
}

const isList = (t: TypeInfo) => t.kind === 'object' && !!t.ofType;
const unwrapped = (t: TypeInfo): TypeInfo => (t.ofType ? unwrapped(t.ofType) : t);
```

*Edge cases:* **list amplification** â€” a nested list field multiplies, so `orders(first: 1000) { items(first: 1000) { variants { price } } }` must be priced at 10^6, not counted as 4 fields; a field count limit alone is trivially bypassed (debugging/interview favourite); `first: 1000` vs a schema cap of 100 â€” price what you will actually serve, and clamp the argument *before* it reaches the resolver; **fragment cycles** (`fragment A on T { ...B } fragment B on T { ...A }`) cause infinite recursion and a stack overflow, so track the visiting set; **unknown fragments**; unions and interfaces (only inline fragments select further fields, and the branches are alternatives, not cumulative â€” charging the sum over-counts, charging the max under-counts for authorization, so be deliberate); a cost of 0 for a query that only has introspection fields (and remember introspection is off in production anyway); the estimation happening **before execution**, so a rejection costs nothing; a hard server-side timeout as a second line of defence for a query that under-estimates; and combining this with a per-operation token bucket so a *repeated* expensive query is throttled by cost rather than rejected every time.

---

topics.bodyMarkdown:
**Definition:** tRPC is a TypeScript RPC framework where the *server's* types are the contract. A client calls `client.user.byId.query({ id })` and the input type, the output type, and the error type are all inferred from the server implementation. No schema language, no resolver map, no codegen step.

```ts
// ---- context: what every procedure can access ----
import { initTRPC, TRPCError } from '@trpc/server';
import superjson from 'superjson';               // Date, Map, Set, BigInt over JSON

export interface Context {
  db: Database;
  user: AuthUser | null;
  tenantId: string;
  req: Request;                                  // for headers/cookies
}
export async function createContext({ req }: { req: Request }): Promise<Context> {
  const user = await authenticate(req);
  return { db: dbFor(user?.tenantId ?? 'public'), user, tenantId: user?.tenantId ?? 'public', req };
}
const t = initTRPC.context<Context>().create({ transformer: superjson, errorFormatter: toProblemDetails });

// ---- reusable building blocks ----
const timing = t.middleware(async ({ next, path }) => {
  const start = performance.now();
  const result = await next();
  console.log(`${path} took ${Math.round(performance.now() - start)}ms`);
  return result;
});
const authed = t.middleware(({ ctx, next }) => {
  if (!ctx.user) throw new TRPCError({ code: 'UNAUTHORIZED', message: 'Sign in required' });
  return next({ ctx: { ...ctx, user: ctx.user } });   // narrow the type for downstream procedures
});
const rateLimit = t.middleware(async ({ ctx, next, path }) => {
  const { allowed, remaining, resetMs } = await limiter.check(ctx.user?.id ?? ctx.req.ip, path);
  if (!allowed) throw new TRPCError({ code: 'TOO_MANY_REQUESTS', message: 'Slow down' });
  return next({ ctx: { ...ctx, limits: { remaining, resetMs } } });
});
const publicProcedure = t.procedure.use(timing).use(rateLimit);
const protectedProcedure = publicProcedure.use(authed);
```

**Routers and procedures**
```ts
export const appRouter = t.router({
  // health check: public, no auth, cheap, and a good target for a load balancer
  health: publicProcedure.query(() => ({ ok: true, at: new Date() })),

  order: t.router({
    // a procedure can be .use()d on a sub-router, so auth is declared once for a whole domain
    byId: protectedProcedure
      .input(z.object({ id: z.string().uuid() }).strict())
      .query(async ({ input, ctx }) => {
        const order = await ctx.db.orders.findById(input.id, ctx.tenantId);
        if (!order) throw new TRPCError({ code: 'NOT_FOUND', message: 'Order not found' });
        return order;                                // the return type IS the output type
      }),

    list: protectedProcedure
      .input(z.object({
        limit: z.number().int().min(1).max(100).default(20),
        cursor: z.string().nullish(),
        status: z.nativeEnum(OrderStatus).optional(),
      }))
      .query(async ({ input, ctx }) => {
        const rows = await ctx.db.orders.list({ ...input, tenantId: ctx.tenantId });
        return { items: rows, nextCursor: rows.at(-1)?.id ?? null };
      }),

    create: protectedProcedure
      .input(z.object({
        clientMutationId: z.string().uuid(),         // idempotency, schema-visible
        customerEmail: z.string().email(),
        items: z.array(z.object({ sku: z.string(), quantity: z.number().int().min(1) })).min(1).max(50),
      }))
      .mutation(async ({ input, ctx }) => {
        const existing = await ctx.db.idempotency.find(input.clientMutationId, ctx.tenantId);
        if (existing) return existing;                // replay
        const order = await ctx.db.orders.create({ ...input, tenantId: ctx.tenantId });
        await ctx.db.idempotency.save(input.clientMutationId, order, ctx.tenantId);
        return order;
      }),

    // nested router -> a procedure with a dot in its path: order.item.byId
    onStatusChange: protectedProcedure.subscription(({ input, ctx }) =>
      ctx.events.subscribe(`order:${input.id}`, (e) => e.payload)),   // WebSocket adapter
  }),

  admin: t.router({ ... }).use(isAdmin),              // router-level middleware
});
export type AppRouter = typeof appRouter;              // the client infers everything from this
```

**Client**
```ts
import { createTRPCProxyClient, httpBatchLink } from '@trpc/client';

const client = createTRPCProxyClient<AppRouter>({
  links: [httpBatchLink({ url: '/trpc', transformer: superjson })],
});
// autocomplete, completion, and the response type come from the server router type
const order = await client.order.byId.query({ id }, { context: { headers: { authorization: `Bearer ${t}` } } });
```
React bindings: `createTRPCReact<AppRouter>()` gives `trpc.order.byId.useQuery({ id }, { placeholderData: keepPreviousData })` with full type inference and no codegen.

**Adapters**
- `createExpressMiddleware({ router: appRouter, createContext })` â€” mount on Express/NestJS.
- `createHTTPHandler` / `fetchRequestHandler` â€” mount on Hono, a Next.js route handler, Fastify, or anything with a `Request`.
- `wsLink` + `createWSClient` â€” subscriptions.
- Node standalone server, or a Next.js App Router integration where the server router *is* the type source for client components.
- `experimental_standaloneClient` style setups let the server type live in a package shared with a separate client app.

**Honest trade-offs**
- **It needs TypeScript on both ends.** There is no generated SDK for Java, Python, or Go. You *can* call the underlying HTTP endpoint by hand (tRPC's wire format is documented: `GET/POST /trpc/<path>?input=<json>`), but you lose everything that makes it tRPC. So: **not viable as a public or third-party API.** This is the disqualifying limitation and you should say it out loud in an interview.
- **It is HTTP + JSON**, so wire overhead and browser/devtools support are the same as REST. No binary encoding, no HTTP/2 multiplexing from the framework's perspective, no schema registry, no `grpcurl`-style reflection, no cross-language tooling.
- **Caching is limited.** Batching uses `POST`. Without batching, queries can be sent as `GET`, which is cacheable, but you do not get REST's `ETag`/`Cache-Control` story for free and CDNs need configuring for tRPC's URL shape.
- **No independent client deploy.** The client is generated from the server's types, so a breaking server change is a breaking client build. That is a feature if you deploy together (a monorepo, one deploy unit) and a liability if you do not.
- **Refactor safety is superb** inside that boundary: rename a field, the client fails to compile. That safety is the whole point, and it is real.
- **Observability is thinner** than Apollo's plugin ecosystem; you get the same primitives (middleware, per-procedure timing) but fewer batteries.
- **Zod (or another validator) in `.input()`** gives you runtime validation and static inference from one definition â€” a genuinely better ergonomics story than hand-written DTOs plus a separate schema, and better than the `class-validator` + `emitDecoratorMetadata` path. This is the argument tRPC makes most strongly, and it is a good one.

**The fit.** A TypeScript monorepo where the frontend and backend ship together, the API is internal, and iteration speed matters more than cross-language or public access. That is a large and legitimate category â€” most modern web products. It is not a fit for a marketplace, a partner integration, a mobile app in Swift, or a polyglot company.

**Questions**
1. What is tRPC's core idea, and what does it remove?
2. What is tRPC's disqualifying limitation?
3. How do you do validation and get static types from one definition?
4. What does router-level middleware buy you?
5. When is tRPC better than REST for an internal API?

**Model answer, Q2:** "Context: a marketplace with a public API for third-party sellers, a React web app, a Swift iOS app, and a Node BFF. Decision: tRPC for the React app and the BFF only; OpenAPI REST for the public API and a generated or hand-written client for iOS. Reasoning: tRPC's entire value is that the client and the server share TypeScript types, so the contract is the compiler rather than a document or a schema. That value evaporates the moment the other end is not TypeScript, because there is no artifact to consume: tRPC has no schema, no code generation, and no language-agnostic client story, and the type inference is the contract. An iOS team would have to hand-build a client against tRPC's documented wire format â€” a `GET /trpc/order.byId?input={...}` with a JSON envelope â€” and that client gets none of the benefits: no autocomplete, no compile-time checking against the server, and a hand-maintained path that will drift silently the first time a field is renamed. Worse, the drift is invisible from the server side, because the server believes its contract is enforced by types when in fact it is only enforced for the callers that happen to share a language. So I scope tRPC to the boundary where both ends are TypeScript and deploy together, and I use a real interface, a published OpenAPI contract with a CI breaking-change diff, for everything else. Trade-offs: two API styles in one codebase, and a team that learns two sets of conventions. I mitigate that by keeping the boundary crisp: tRPC inside the web app's own surface, OpenAPI at every organizational edge, and no procedure is ever exposed directly to a non-TS caller. Failure scenario: a team adopts tRPC across a polyglot company, the Swift team hand-writes clients against the wire format, and a schema change that is a compile error for the web app ships silently as a runtime decoding error on iOS, where the field arrives `undefined` and a `force`-unwrap crashes. The Swift team's tests covered the old shape, so nothing fails until a user hits the new code path in production."

**Mistakes:** exposing tRPC procedures to non-TypeScript clients; using it for a public API; expecting tRPC's batching to be CDN-cacheable; hand-writing a wire-format client and calling it supported; forgetting `superjson` and then debugging `Date` serialization; not applying tenant scoping in `createContext`; no rate limiting because tRPC "is type safe" (types do not protect a runtime endpoint).

**Mini task:** stand up tRPC with four procedures (list with a cursor, get, create with `clientMutationId` idempotency, and a subscription), `superjson` for dates, a public and a protected procedure with router-level middleware, and rate limiting in middleware with `TOO_MANY_REQUESTS`. Then mount it three ways â€” Express, a Next.js route handler, and a fetch adapter â€” and write a hand-written JavaScript client against the wire format to see exactly what tRPC's non-TS story looks like.

---

**How to practice:** write each from memory on a blank file, then test against the edge cases listed. In an interview, state your assumptions out loud, implement the main path, then *say* which edge cases you would handle next â€” the reasoning about edges is what separates a mid-level from a senior.

These nine are the highest-leverage exercises in this part. Each is small enough to write in 20-30 minutes and deep enough to be a real signal.

---

### 1. DataLoader: per-request batching + caching

**The contract:** many `load(key)` calls in the same tick produce exactly **one** call to the batch function; the same key loaded twice (across ticks, within the request) is fetched once; each promise settles independently.

```ts
type BatchFn<K, V> = (keys: readonly K[]) => PromiseLike<Array<V | Error>>;

export class DataLoader<K, V> {
  #cache = new Map<K, Promise<V>>();
  #queue: K[] = [];
  #pending: Array<{ resolve: (v: V) => void; reject: (e: Error) => void }> = [];
  #scheduled = false;

  constructor(
    private readonly batchFn: BatchFn<K, V>,
    private readonly options: { maxBatchSize?: number; cache?: boolean } = {},
  ) {}

  load(key: K): Promise<V> {
    if (this.options.cache === false) return this.#immediate(key);
    const hit = this.#cache.get(key);
    if (hit) return hit;
    const p = new Promise<V>((resolve, reject) => {
      this.#queue.push(key);
      this.#pending.push({ resolve, reject });
    });
    p.catch(() => this.#cache.delete(key));    // never cache a failure: a later field can retry
    this.#cache.set(key, p);
    this.#schedule();
    return p;
  }

  loadMany(keys: readonly K[]): Promise<Array<V | Error>> {
    return Promise.all(keys.map((k) => this.load(k).catch((e) => e as Error)));
  }
  // Bypass the cache and the batching queue: one direct round trip, one promise.
  // Takes a single key, not an array â€” returning a scalar V from an array
  // parameter only works by accident, and a legitimately `null` value would be
  // collapsed into the "arity mismatch" branch by `??`.
  async #immediate(key: K): Promise<V> {
    const values = await this.batchFn([key]);
    if (values.length !== 1) throw new Error(`batchFn returned ${values.length} values for 1 key`);
    const only = values[0];
    if (only instanceof Error) throw only;      // per-key error semantics, not an arity fault
    return only;
  }
  prime(key: K, value: V): void { this.#cache.set(key, Promise.resolve(value)); }
  clear(key: K): void { this.#cache.delete(key); }
  clearAll(): void { this.#cache.clear(); }

  #schedule(): void {
    if (this.#scheduled) return;
    this.#scheduled = true;
    // A microtask, not setTimeout(0): the whole selection level settles its
    // load() calls before we touch the database.
    queueMicrotask(() => { this.#scheduled = false; void this.#flush(); });
  }

  async #flush(): Promise<void> {
    if (this.#queue.length === 0) return;
    const keys = this.#queue, pending = this.#pending;
    this.#queue = []; this.#pending = [];
    try { await this.#dispatch(keys, pending); }
    catch (err) { for (const p of pending) p.reject(err as Error); }
  }

  async #dispatch(keys: K[], pending: Array<{ resolve: (v: V) => void; reject: (e: Error) => void }>): Promise<void> {
    const size = this.options.maxBatchSize ?? keys.length;
    for (let i = 0; i < keys.length; i += size) {
      const ks = keys.slice(i, i + size);
      const ps = pending.slice(i, i + size);
      let values: Array<V | Error>;
      try { values = await this.batchFn(ks); }
      catch (err) { for (const p of ps) p.reject(err as Error); continue; }
      if (values.length !== ks.length) {
        for (const p of ps) p.reject(new Error(`batchFn returned ${values.length} values for ${ks.length} keys`));
        continue;
      }
      ks.forEach((_, j) =>
        values[j] instanceof Error ? ps[j].reject(values[j] as Error) : ps[j].resolve(values[j] as V));
    }
  }
}

// ---- one loader set per request ----
export function createLoaders(db: Db) {
  return {
    userById: new DataLoader<string, User>((ids) => db.user.findManyByIds([...ids])),
    productBySku: new DataLoader<string, Product>((skus) => db.product.findManyBySkus([...skus]), {
      maxBatchSize: 500,
    }),
  };
}
// SQL behind the batch function â€” one set-based query, not a loop:
//   SELECT * FROM users WHERE id = ANY($1::uuid[]);
```

*Edge cases:* duplicate keys in one batch; a batch function that resolves with the wrong length; a batch function that *throws* (every key in that slice rejects); `maxBatchSize` splitting a tick into several round trips; caching an `Error`; `cache: false`; `loadMany` returning per-key `Error` values (the DataLoader spec's semantics) rather than rejecting; `prime()` for data you already have; a rejected key not poisoning the cache.

*Follow-ups:* why `queueMicrotask` and not `setTimeout(0)`; how to share the cache across requests safely (you cannot, without invalidation â€” that is a cache, not a loader); how to thread an `AbortSignal` into the batch function.

---

### 2. Relay-style connection paginator with opaque cursors

**The contract:** `first`/`after` and `last`/`before` both work; cursors are opaque, signed, and versioned; a page is exactly `limit + 1` rows fetched so `hasNextPage` is exact rather than guessed.

```ts
import { createHmac, timingSafeEqual } from 'node:crypto';

export interface PageInfo { hasNextPage: boolean; hasPreviousPage: boolean; startCursor: string | null; endCursor: string | null }
export interface Edge<T> { cursor: string; node: T }
export interface ConnectionArgs { first?: number; last?: number; after?: string; before?: string }
export interface Key { createdAt: string; id: string }        // sort key + unique tiebreaker
export class BadCursor extends Error { readonly code = 'BAD_CURSOR' }

const VERSION = 1;
const secret = process.env.CURSOR_SECRET!;

export function encodeCursor(key: Key): string {
  const payload = Buffer.from(JSON.stringify({ v: VERSION, ...key })).toString('base64url');
  const sig = createHmac('sha256', secret).update(payload).digest('base64url').slice(0, 16);
  return `${payload}.${sig}`;
}

export function decodeCursor(cursor: string): Key {
  const dot = cursor.lastIndexOf('.');
  if (dot < 0) throw new BadCursor('malformed cursor');
  const payload = cursor.slice(0, dot);
  const given = Buffer.from(cursor.slice(dot + 1));
  const want = Buffer.from(createHmac('sha256', secret).update(payload).digest('base64url').slice(0, 16));
  if (given.length !== want.length || !timingSafeEqual(given, want)) throw new BadCursor('bad signature');
  const parsed = JSON.parse(Buffer.from(payload, 'base64url').toString()) as { v: number } & Key;
  if (parsed.v !== VERSION) throw new BadCursor('cursor version mismatch');
  return { createdAt: parsed.createdAt, id: parsed.id };
}

// Forward: strictly "older than the cursor". Backward: strictly "newer".
const forward = (after: Key | null) => after ? '(created_at, id) < ($1, $2)' : 'TRUE';
const backward = (before: Key | null) => before ? '(created_at, id) > ($1, $2)' : 'TRUE';

export function buildSql(args: ConnectionArgs): { sql: string; params: unknown[] } {
  const isForward = args.first !== undefined || args.after !== undefined;
  if (args.first !== undefined && args.last !== undefined) throw new Error('first and last are mutually exclusive');
  const where = isForward ? forward(args.after ? decodeCursor(args.after) : null)
                          : backward(args.before ? decodeCursor(args.before) : null);
  const order = isForward ? 'ORDER BY created_at DESC, id DESC' : 'ORDER BY created_at ASC, id ASC';
  const limit = Math.min(isForward ? args.first ?? 20 : args.last ?? 20, 200);
  return {
    // limit + 1 -> the extra row is the "is there more" signal, no COUNT(*) needed
    sql: `SELECT id, created_at, status, total FROM orders WHERE ${where} ${order} LIMIT $1`,
    params: [limit + 1],
  };
}

export function connectionFromRows<T extends Key>(rows: T[], args: ConnectionArgs) {
  const isForward = args.first !== undefined || args.after !== undefined;
  const limit = Math.min(isForward ? args.first ?? 20 : args.last ?? 20, 200);
  if (limit < 0) throw new RangeError('first/last must be >= 0');
  if (args.first !== undefined && args.last !== undefined) throw new Error('first and last are mutually exclusive');

  let slice = rows;
  if (isForward && args.after) {
    const a = decodeCursor(args.after);
    slice = rows.filter((r) => r.createdAt < a.createdAt || (r.createdAt === a.createdAt && r.id < a.id));
  } else if (!isForward && args.before) {
    const b = decodeCursor(args.before);
    slice = rows.filter((r) => r.createdAt > b.createdAt || (r.createdAt === b.createdAt && r.id > b.id));
  }

  const hasExtra = slice.length > limit;
  const page = hasExtra ? slice.slice(0, limit) : slice;
  const edges = page.map((node) => ({ cursor: encodeCursor({ createdAt: node.createdAt, id: node.id }), node }));
  return {
    edges,
    pageInfo: {
      hasNextPage: isForward ? hasExtra : page.length > 0,
      hasPreviousPage: isForward ? args.after !== undefined : hasExtra,
      startCursor: edges[0]?.cursor ?? null,
      endCursor: edges.at(-1)?.cursor ?? null,
    },
  };
}
// Index requirement: CREATE INDEX ON orders (status, created_at DESC, id DESC);
```

*Edge cases:* `first` and `last` together; `first: 0`; `first: -1`; `after` **and** `before` (a window); a tampered cursor (must be an error, never a silent reset); a cursor from a different sort or a different list (sign the scope into the payload, or store the scope in the cursor); a non-unique sort column (see #4); the `hasPreviousPage` truth table; an empty page (`startCursor: null`); a cursor older than your retention (decide: `400` with a clear code, or a fresh start â€” never silent).

