  CLOSED â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â–¶ OPEN
                                      â”‚  on('message') / on('ping') / send()
                                      â–¼
                                   ACTIVE â”€â”€â”€ send() while bufferedAmount > limit â”€â”€â–¶ BACKPRESSURED
                                      â”‚                                              â”‚  bufferedAmount drains
                                      â”‚  close() sent                                  â–¼
                                      â–¼                                            ACTIVE
                                  CLOSING â”€â”€â”€ peer replies close / socket ends â”€â”€â–¶ CLOSED
  CLOSED â—€â”€â”€â”€â”€â”€ error, terminate(), TCP reset, or timeout â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”˜
```
```ts
// backpressure: the single most under-implemented part of a WebSocket server
const MAX_BUFFERED = 4 * 1024 * 1024;
