  if (ws.readyState !== WebSocket.OPEN) return false;
  if (ws.bufferedAmount > MAX_BUFFERED) {
    logger.warn({ buffered: ws.bufferedAmount }, 'dropping message â€” slow consumer');
    ws.close(1013, 'client too slow');
    return false;                       // the alternative â€” buffering forever â€” is an OOM
  }
  ws.send(payload);
  return true;
