### 7. A tenant-scoped data-access layer with RLS and an isolation test harness

**The contract:** tenant scope is a required argument on every repository method; the layer injects it into every query; the database enforces it with RLS as a backstop; cache keys and job payloads are tenant-prefixed by construction; and a generated test proves no route can read another tenant's rows.

```sql
-- Layer 1: enforcement in the database. `with check` blocks bad WRITES;
-- `force` closes the table-owner bypass. Both are required.
alter table orders       enable row level security;
alter table orders       force  row level security;
alter table order_items  enable row level security;
alter table order_items  force  row level security;

create policy orders_tenant on orders
  using      (tenant_id = current_setting('app.tenant_id', true)::uuid)
  with check (tenant_id = current_setting('app.tenant_id', true)::uuid);
create policy order_items_tenant on order_items
  using      (tenant_id = current_setting('app.tenant_id', true)::uuid)
  with check (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- No such policy => no rows visible. Absence is the SAFE default, which is why
-- `current_setting(..., true)` returning NULL (unset) yields no rows rather than all rows.
create unique index orders_tenant_ref on order_items (tenant_id, order_id, sku);
```
```ts
export type TenantId = string & { readonly __brand: 'TenantId' };

export class TenantContext {
  constructor(readonly tenantId: TenantId, readonly userId: string) {}
}

/** The only way to obtain a queryable in tenant scope. There is no unscoped export. */
export class TenantDb {
  constructor(private pool: Pool, private cache: Cache, private ctx: TenantContext) {}

  /** Every tenant-scoped transaction sets the GUC transaction-locally on the
   *  connection it holds. A session-level `set` leaks to the next borrower. */
  async tx<T>(fn: (q: Queryable) => Promise<T>): Promise<T> {
    const client = await this.pool.connect();
    try {
      await client.query('begin');
      await client.query('select set_config($1, $2, true)', ['app.tenant_id', this.ctx.tenantId]);
      const out = await fn(new Queryable(client));
      await client.query('commit');
      return out;
    } catch (e) {
      await client.query('rollback').catch(() => {});
      throw e;
    } finally { client.release(); }
  }

  /**
   * Cache keys are built ONLY here, and a tenant is a required parameter.
   * This is what stops the "cache key without a tenant" leak â€” the most common
   * cross-tenant leak in otherwise-correct code.
   */
  key(...parts: (string | number)[]): string {
    return `t:${this.ctx.tenantId}:${parts.join(':')}`;
  }

  async remember<T>(key: string, ttlSec: number, load: () => Promise<T>): Promise<T> {
    const k = this.key(key);
    const hit = await this.cache.get(k);
    if (hit !== null) return JSON.parse(hit) as T;
    const val = await load();
    await this.cache.set(k, JSON.stringify(val), ttlSec);
    return val;
  }
}

/** A repository where tenantId cannot be forgotten: it comes from the context. */
export class OrderRepo {
  constructor(private db: TenantDb) {}
  // No tenantId parameter exists. A caller CANNOT forget to pass it.
  async findById(id: string) {
    return this.db.remember(`order:${id}`, 60, async () => {
      const rows = await this.db.tx(q => q.query(
        `select id, status, total_cents, currency, created_at from orders where id = $1`, [id]));
      return rows[0] ?? null;                 // the RLS policy makes the tenant predicate implicit
    });
  }
  async list(q: { status?: string; limit: number }) {
    return this.db.tx(txq => txq.query(
      `select id, status, total_cents, created_at from orders
       where ($1::text is null or status = $1)
       order by created_at desc, id desc limit $2`, [q.status ?? null, q.limit]));
  }
}

/** Jobs carry the tenant explicitly, because they have no request context. */
export interface TenantJob<P = unknown> {
  jobId: string;                              // deterministic: dedupes retries
  tenantId: TenantId;
  kind: string;
  payload: P;
  enqueuedAt: string;
}

export async function withJobTenant<P, R>(db: TenantDb, job: TenantJob<P>, fn: () => Promise<R>) {
  // Validate the tenant id FORMAT. A missing field is a shared tenant, which is
  // the root cause of "works in tests, leaks in production".
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(job.tenantId)) {
    throw new Error(`job ${job.jobId} has an invalid tenantId`);
  }
  return fn();
}
```
```ts
// The isolation harness: generate one test per ROUTE, not per route someone remembered.
export function isolationSuite(routeTable: RouteDef[], ctx: TestCtx) {
  describe('tenant isolation', () => {
    const A = ctx.tenant('A'), B = ctx.tenant('B');

    for (const route of routeTable.filter(r => r.method !== 'DELETE')) {
      it(`${route.method} ${route.path} as A cannot see B's data`, async () => {
        // Seed a B row with BOTH an id and a distinctive value, because a leak
        // that renames the id still returns the data.
        const bRow = await ctx.seed(B, route.resource, { id: 'b-1', note: 'B-SECRET-9f3' });

        const res = await ctx.as(A).request(route).set(ctx.queryFor(route));
        expect(res.status).toBeLessThan(500);
        const body = JSON.stringify(res.body);
        expect(body).not.toContain(bRow.id);
        expect(body).not.toContain('B-SECRET-9f3');
        // Also assert the POSITIVE case: the endpoint works when the owner asks.
        const ok = await ctx.as(B).request(route).set(ctx.queryFor(route));
        expect(ok.status).toBe(200);
      });
    }

    it('an unscoped raw query returns nothing', async () => {
      const rows = await ctx.rawDb(A).query('select * from orders limit 5');   // no set_config
      expect(rows).toHaveLength(0);   // unset GUC => the policy matches nothing
    });

    it('a cross-tenant write is rejected by with check', async () => {
      await expect(
        ctx.rawDb(A).query(`insert into orders (tenant_id, id) values ($1::uuid, gen_random_uuid())`, [B.id]),
      ).rejects.toThrow();   // the write is blocked at the database
    });
  });
}
```

*Edge cases:* an unset `app.tenant_id` (must yield zero rows, not all rows â€” verify the policy uses `current_setting(..., true)` and compare with `NULL`); a connection returned to the pool without `rollback` (the next borrower's `begin` inherits a partial transaction); `current_setting` inside a function called outside an explicit transaction (session-level state persists â€” always wrap); a repository method that uses a *different* pooled client than the one that ran `set_config`; a cache key built in one module and read in another with a different context; a test fixture with `tenant_id = null` (a shared tenant that passes everything until production); an admin/support query that legitimately needs cross-tenant access (a separate audited role, never the default).

*Follow-ups:* how you would handle shared tables with no tenant (a `countries` lookup must be readable by all â€” grant a read-only policy); how you would migrate to schema-per-tenant without changing the repository interface; how you would run a periodic production sampler that asserts every query touched exactly one tenant.

